sections.css:
.hero{position: relative; height: 100vh; overflow: hidden; display: flex; align-items: center; justify-content: center;}
.video-portal{position: absolute; inset: 0px; z-index: 0;}
.video-portal video{width: 100%; height: 100%; object-fit: cover; filter: brightness(0.75);}
.video-portal::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(ellipse 80% 100% at 50% 60%,transparent 45%,var(--midnight) 92%); pointer-events: none;}
.atmospheric-mask{position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 75vw; height: 65vh; z-index: 1; border-radius: 60% 40% 55% 45% / 45% 55% 40% 60%; mask-image: radial-gradient(85% 85%, black 40%, transparent 75%); animation: 18s ease-in-out 0s infinite normal none running blob-drift; overflow: hidden;}
.atmospheric-mask video{width: 130%; height: 130%; object-fit: cover; margin: -15%;}
.light-corridor{position: absolute; inset: 0px; z-index: 2; pointer-events: none; background: radial-gradient(oklch(0.85 0.08 30 / 0.18) 0%, oklch(0.75 0.1 340 / 0.07) 40%, transparent 80%);}
.hero-content{position: relative; z-index: 10; text-align: center; max-width: 900px; padding: 0px 2rem;}
.hero-eyebrow{font-family: var(--data); font-size: 0.72rem; font-weight: 400; letter-spacing: 0.35em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 2rem; opacity: 0; animation: 1.2s ease 0.4s 1 normal forwards running fade-rise;}
.hero-title{font-family: var(--serif); font-size: clamp(3.2rem, 8vw, 8rem); line-height: 0.9; margin-bottom: 1.5rem; opacity: 0; animation: 1.4s ease 0.6s 1 normal forwards running fade-rise;}
.hero-title em{font-style: italic; color: var(--amber); display: block;}
.hero-subtitle{font-family: var(--data); font-size: 0.9rem; font-weight: 300; color: var(--text-secondary); letter-spacing: 0.08em; max-width: 480px; margin: 0px auto 3rem; line-height: 1.7; opacity: 0; animation: 1.4s ease 0.9s 1 normal forwards running fade-rise;}
.hero-cta-group{display: flex; align-items: center; justify-content: center; gap: 1.5rem; opacity: 0; animation: 1.2s ease 1.2s 1 normal forwards running fade-rise;}
.btn-liquid{position: relative; padding: 1rem 2.5rem; border-radius: 40% 60% 70% 30% / 40% 50% 60%; border: 1px solid var(--glass-border-hover); background: oklch(0.85 0.08 45 / 0.08); color: var(--text-primary); font-family: var(--data); font-size: 0.82rem; letter-spacing: 0.15em; text-transform: uppercase; cursor: none; overflow: hidden; transition: border-radius 0.6s, border-color 0.3s, background 0.3s; text-decoration: none; display: inline-flex; align-items: center; gap: 0.75rem;}
.btn-liquid::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at var(--mx,50%) var(--my,50%),oklch(85% 0.1 45 / 0.25) 0%,transparent 60%); opacity: 0; transition: opacity 0.3s;}
.btn-liquid::after{content: ""; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: conic-gradient(transparent 30%, oklch(0.85 0.1 45 / 0.15) 40%, transparent 50%); animation: 4s linear 0s infinite normal none running shimmer-spin; opacity: 0; transition: opacity 0.4s;}
.btn-liquid:hover{border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; border-color: oklch(0.85 0.1 45 / 0.5); background: oklch(0.85 0.08 45 / 0.15);}
.btn-liquid:hover::before, .btn-liquid:hover::after{opacity: 1;}
.btn-ghost{padding: 1rem 2rem; background: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; color: var(--text-muted); font-family: var(--data); font-size: 0.82rem; letter-spacing: 0.12em; text-transform: uppercase; cursor: none; transition: color 0.3s; text-decoration: none;}
.btn-ghost:hover{color: var(--text-secondary);}
.scroll-hint{position: absolute; bottom: 3rem; left: 50%; transform: translateX(-50%); z-index: 10; display: flex; flex-direction: column; align-items: center; gap: 0.75rem; opacity: 0; animation: 1s ease 2s 1 normal forwards running fade-rise;}
.scroll-hint span{font-family: var(--data); font-size: 0.65rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--text-muted);}
.scroll-line{width: 1px; height: 48px; background: linear-gradient(to bottom,var(--amber-glow),transparent); animation: 2s ease-in-out 0s infinite normal none running scroll-pulse;}
