section{padding: 8rem 0px;}
.container{max-width: 1320px; margin: 0px auto; padding: 0px 4rem;}
.section-label{font-family: var(--data); font-size: 0.65rem; letter-spacing: 0.4em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 1rem;}
.manifesto{background: transparent; position: relative;}
.manifesto::before{content: ""; position: absolute; top: 0px; left: 50%; transform: translateX(-50%); width: 70vw; height: 100%; background: radial-gradient(100% 80% at 50% 30%, oklch(0.85 0.08 45 / 0.06), transparent 70%); pointer-events: none;}
