.metric-orb{padding: 2.5rem 2rem; border-radius: 40% 60% 55% 45% / 50% 40% 60% 50%; background: var(--glass-bg); border: 1px solid var(--glass-border); backdrop-filter: blur(20px); text-align: center; transition: border-radius 0.8s, border-color 0.4s, transform 0.4s; animation-duration: ; animation-timing-function: ; animation-iteration-count: ; animation-direction: ; animation-fill-mode: ; animation-play-state: ; animation-name: ; animation-timeline: ; animation-range-start: ; animation-range-end: ; animation-delay: var(--delay,0s);}
.metric-orb:hover{border-radius: 60% 40% 45% 55% / 40% 60% 50%; border-color: oklch(0.85 0.1 45 / 0.35); transform: translateY(-4px);}
.metric-value{font-family: var(--serif); font-size: 3rem; color: var(--amber); line-height: 1; margin-bottom: 0.5rem;}
.metric-label{font-family: var(--data); font-size: 0.72rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--text-muted);}
.reveal-up{opacity: 0; transform: translateY(40px); transition: opacity 0.9s, transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal-up.visible{opacity: 1; transform: none;}

section{padding: 8rem 0px;}
.container{max-width: 1320px; margin: 0px auto; padding: 0px 4rem;}
.section-label{font-family: var(--data); font-size: 0.65rem; letter-spacing: 0.4em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 1rem;}
.pillars{padding: 8rem 0px; position: relative;}
.pillars::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(80% 60% at 20% 50%, oklch(0.72 0.08 160 / 0.06), transparent 60%), radial-gradient(60% 80% at 80% 60%, oklch(0.75 0.1 340 / 0.05), transparent 60%); pointer-events: none;}
.pillars-header{text-align: center; margin-bottom: 5rem;}
.pillars-header h2{font-family: var(--serif); font-size: clamp(2rem, 3.5vw, 3.5rem); line-height: 1.1;}
.pillars-header h2 em{font-style: italic; color: var(--sage);}
.pillars-header p{font-family: var(--data); font-size: 0.9rem; font-weight: 300; color: var(--text-muted); max-width: 500px; margin: 1.5rem auto 0px; line-height: 1.7;}
.pillars-flow{display: grid; grid-template-columns: repeat(4, 1fr); gap: 0px; position: relative;}
.pillar-card{padding: 3rem 2rem; position: relative; border-radius: 40% 60% 70% 30% / 40% 50% 60%; background: oklch(0.16 0.02 260 / 0.6); border: 1px solid var(--glass-border); margin: 0.75rem; backdrop-filter: blur(16px); transition: border-radius 0.9s, transform 0.4s, background 0.4s, border-color 0.4s; overflow: hidden;}
.pillar-card::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at 50% 0%,var(--card-glow,oklch(85% 0.1 45 / 0.1)) 0%,transparent 60%); opacity: 0; transition: opacity 0.4s;}
.pillar-card:hover{border-radius: 60% 40% 30% 70% / 50% 60% 40% 50%; transform: translateY(-8px) rotate(-0.5deg); background: oklch(0.18 0.03 260 / 0.75); border-color: var(--glass-border-hover);}
.pillar-card:hover::before{opacity: 1;}
.pillar-card:nth-child(2){--card-glow: oklch(72% 0.08 160 / 0.12);}
.pillar-card:nth-child(3){--card-glow: oklch(75% 0.1 340 / 0.1);}
.pillar-card:nth-child(4){--card-glow: oklch(75% 0.12 250 / 0.1);}
.pillar-icon{width: 48px; height: 48px; margin-bottom: 1.75rem; border-radius: 50%; background: oklch(0.85 0.08 45 / 0.08); border: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: center;}
.pillar-icon svg{width: 22px; height: 22px; stroke: var(--amber); fill: none; stroke-width: 1.5;}
.pillar-card:nth-child(2) .pillar-icon svg{stroke: var(--sage);}
.pillar-card:nth-child(3) .pillar-icon svg{stroke: oklch(0.75 0.1 340);}
.pillar-card:nth-child(4) .pillar-icon svg{stroke: oklch(0.72 0.1 250);}
.pillar-tag{font-family: var(--data); font-size: 0.62rem; letter-spacing: 0.3em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 0.75rem;}
.pillar-title{font-family: var(--serif-alt); font-size: 1.4rem; margin-bottom: 1rem; color: var(--text-primary);}
.pillar-body{font-family: var(--data); font-size: 0.82rem; line-height: 1.8; color: var(--text-muted); font-weight: 300;}
.breeze-word{display: inline-block; transition: transform 0.1s;}
.reveal-up{opacity: 0; transform: translateY(40px); transition: opacity 0.9s, transform 0.9s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal-up.visible{opacity: 1; transform: none;}

